-- LeaveFlow initial schema.
-- Timestamps are stored as TIMESTAMPTZ (UTC); calendar dates (leave days, holidays) as DATE.

-- Employee codes (EMP-0001, EMP-0002, ...) are generated by the database on insert.
CREATE SEQUENCE employee_code_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE employees (
    id              BIGSERIAL PRIMARY KEY,
    employee_code   VARCHAR(20)  NOT NULL UNIQUE
                    DEFAULT ('EMP-' || LPAD(nextval('employee_code_seq')::TEXT, 4, '0')),
    full_name       VARCHAR(100) NOT NULL,
    email           VARCHAR(150) NOT NULL UNIQUE,
    password_hash   VARCHAR(100) NOT NULL,
    role            VARCHAR(20)  NOT NULL,
    department      VARCHAR(100) NOT NULL,
    designation     VARCHAR(100) NOT NULL,
    manager_id      BIGINT REFERENCES employees (id),
    joining_date    DATE         NOT NULL,
    active          BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_employees_role CHECK (role IN ('ADMIN', 'MANAGER', 'EMPLOYEE')),
    CONSTRAINT chk_employees_not_own_manager CHECK (manager_id IS NULL OR manager_id <> id)
);

CREATE INDEX idx_employees_manager ON employees (manager_id);

CREATE TABLE leave_types (
    id              BIGSERIAL PRIMARY KEY,
    code            VARCHAR(20)  NOT NULL UNIQUE,
    name            VARCHAR(50)  NOT NULL,
    description     VARCHAR(255),
    annual_quota    INTEGER,                      -- NULL means unlimited (e.g. unpaid leave)
    color           VARCHAR(7)   NOT NULL,        -- hex colour used by the frontend
    CONSTRAINT chk_leave_types_quota CHECK (annual_quota IS NULL OR annual_quota >= 0)
);

CREATE TABLE public_holidays (
    id              BIGSERIAL PRIMARY KEY,
    holiday_date    DATE         NOT NULL UNIQUE,
    name            VARCHAR(100) NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE TABLE leave_requests (
    id              BIGSERIAL PRIMARY KEY,
    employee_id     BIGINT       NOT NULL REFERENCES employees (id),
    leave_type_id   BIGINT       NOT NULL REFERENCES leave_types (id),
    start_date      DATE         NOT NULL,
    end_date        DATE         NOT NULL,
    working_days    INTEGER      NOT NULL,
    reason          VARCHAR(500) NOT NULL,
    status          VARCHAR(20)  NOT NULL,
    reviewed_by     BIGINT REFERENCES employees (id),
    review_comment  VARCHAR(500),
    reviewed_at     TIMESTAMPTZ,
    version         BIGINT       NOT NULL DEFAULT 0,   -- optimistic locking
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_leave_requests_dates CHECK (end_date >= start_date),
    CONSTRAINT chk_leave_requests_working_days CHECK (working_days > 0),
    CONSTRAINT chk_leave_requests_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED'))
);

CREATE INDEX idx_leave_requests_employee ON leave_requests (employee_id);
CREATE INDEX idx_leave_requests_status ON leave_requests (status);
CREATE INDEX idx_leave_requests_dates ON leave_requests (start_date, end_date);

-- Audit trail: one row per status change of a leave request.
CREATE TABLE leave_request_history (
    id                BIGSERIAL PRIMARY KEY,
    leave_request_id  BIGINT      NOT NULL REFERENCES leave_requests (id) ON DELETE CASCADE,
    from_status       VARCHAR(20),                 -- NULL for the initial "submitted" entry
    to_status         VARCHAR(20) NOT NULL,
    changed_by        BIGINT      NOT NULL REFERENCES employees (id),
    comment           VARCHAR(500),
    changed_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_leave_request_history_request ON leave_request_history (leave_request_id);
